/* ---------- Rotina do acampamento: faixas, áreas de treino, captura da bandeira, regras, oferenda ---------- */
var FX_NOMES={'06':'Alvorada','09':'Treinos','12':'Refeitório','15':'Arena','18':'Jantar','21':'Fogueira'};
var AREAS=[[/nata|piscin/i,'Lago das canoas'],[/academ|muscul|malha|treino/i,'Muro de escalada'],[/quest/i,'Arena'],
 [/estud|trf|concurso|revis/i,'Campo de arquearia'],[/ler|leitura|livro/i,'Biblioteca'],[/água|agua/i,'Fonte'],
 [/sono|dormir|cama/i,'Chalé'],[/medit|respir/i,'Bosque'],[/corr|caminh|passo/i,'Trilha']];
function acSemana(d){d=d||new Date();var x=new Date(d.getFullYear(),d.getMonth(),d.getDate());var w=(x.getDay()+6)%7;x.setDate(x.getDate()-w);
 return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');}
